INSERT INTO venue(name,address,introduction,opening_hours) VALUES('市文化博物馆','文化路十八号','面向公众开放的文化博物馆，提供文化展览与传统手工体验。','周二至周日 09:00—17:00'),('社区文化艺术中心','艺术街六号','开展文化讲座、社区展览与艺术体验活动的公共文化空间。','09:00-18:00');
INSERT INTO activity(venue_id,title,description,category,audience,status,plan,notice,copywriting) VALUES(1,'非遗剪纸体验','跟随非遗手工老师认识剪纸艺术，亲手制作一份独特的文化作品。','HERITAGE','亲子家庭','PUBLISHED','文化介绍、动手体验、作品分享','一个账号限预约一个名额，请按场次时间准时到场。','在一剪一刻之间，发现传统纸艺之美。'),(1,'博物馆里的故事','走进馆藏文物背后的历史，在讲解员的带领下发现城市文化故事。','LECTURE','不限人群','PUBLISHED','','',''),(2,'社区摄影入门','从构图与光线开始学习摄影，用镜头记录身边的社区生活。','ART','不限人群','PUBLISHED','','','');
